<h1>Admission requirements</h1><p>Configure cycle-wide rules or narrow them to one programme opening. No school-specific rules are hard-coded.</p><?php if (session('message')): ?><p><?= esc(session('message')) ?></p><?php endif ?><?php if (session('errors')): ?><ul><?php foreach(session('errors') as $error): ?><li><?= esc($error) ?></li><?php endforeach ?></ul><?php endif ?>
<?php $scopeFields = static function() use($cycles,$programmeOpenings): string { ob_start(); ?><label>Cycle <select name="admission_cycle_id" required><?php foreach($cycles as $cycle): ?><option value="<?= esc($cycle['id']) ?>"><?= esc($cycle['title']) ?></option><?php endforeach ?></select></label><label>Programme opening <select name="programme_opening_id"><option value="">Cycle-wide</option><?php foreach($programmeOpenings as $opening): ?><option value="<?= esc($opening['id']) ?>">#<?= esc($opening['id']) ?></option><?php endforeach ?></select></label><?php return ob_get_clean(); }; ?>
