<form method="post" action="<?= site_url('tenant/admissions/requirements/subjects') ?>" class="admin-card"><?= csrf_field() ?><h2>O Level subject rule</h2><?= $scopeFields() ?><label>ID for update <input name="id" inputmode="numeric"></label><label>Subject code <input name="subject_code" required></label><label>Subject name <input name="subject_name" required></label><label>Minimum grade <input name="minimum_grade"></label><label>Alternative group <input name="requirement_group"></label><label>Status <select name="status"><option>active</option><option>archived</option></select></label><input type="hidden" name="is_required" value="0"><label><input type="checkbox" name="is_required" value="1" checked> Required</label><button>Save subject</button></form>
<form method="post" action="<?= site_url('tenant/admissions/requirements/documents') ?>" class="admin-card"><?= csrf_field() ?><h2>Private document rule</h2><?= $scopeFields() ?><label>ID for update <input name="id" inputmode="numeric"></label><label>Document type <input name="document_type" required></label><label>Label <input name="label" required></label><label>Allowed MIME types <input name="allowed_mime_types" value="application/pdf,image/jpeg,image/png" required></label><label>Maximum bytes <input name="maximum_size_bytes" value="5242880" inputmode="numeric" required></label><label>Status <select name="status"><option>active</option><option>archived</option></select></label><input type="hidden" name="is_required" value="0"><label><input type="checkbox" name="is_required" value="1" checked> Required</label><button>Save document rule</button></form></section>
